import base64
import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _safe_get(obj: Any, *keys: str) -> Any:
    cur = obj
    for key in keys:
        if cur is None:
            return None
        if isinstance(cur, dict):
            cur = cur.get(key)
        else:
            cur = getattr(cur, key, None)
    return cur


def _to_number(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, dict):
        for k in ("Value", "value", "Text", "text", "Amount", "amount"):
            if k in value:
                return _to_number(value[k])
        return None
    s = str(value).strip()
    if not s:
        return None
    cleaned = "".join(ch for ch in s if ch.isdigit() or ch in ".-,")
    cleaned = cleaned.replace(",", "")
    try:
        return float(cleaned)
    except Exception:
        return None


def _extract_text(field: Any) -> Optional[str]:
    if field is None:
        return None
    if isinstance(field, str):
        return field
    if isinstance(field, dict):
        for k in ("Value", "value", "Text", "text", "DisplayValue", "display_value"):
            if k in field and field[k] is not None:
                return str(field[k]).strip() or None
        if "ValueString" in field and field["ValueString"] is not None:
            return str(field["ValueString"]).strip() or None
    for attr in ("Value", "Text", "DisplayValue", "value", "text", "display_value"):
        v = getattr(field, attr, None)
        if v is not None:
            return str(v).strip() or None
    return str(field).strip() or None


def _normalize_line_items(expense_docs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for doc in expense_docs:
        line_item_groups = doc.get("LineItemGroups") or []
        for group in line_item_groups:
            line_items = group.get("LineItems") or []
            for li in line_items:
                item: Dict[str, Any] = {}
                if isinstance(li, dict):
                    for field in li.get("LineItemExpenseFields", []):
                        if not isinstance(field, dict):
                            continue
                        ftype = _safe_get(field, "Type", "Text") or _safe_get(field, "Type", "Value")
                        if isinstance(ftype, dict):
                            ftype = ftype.get("Text") or ftype.get("Value")
                        key = str(ftype).lower() if ftype else ""
                        value = _extract_text(field.get("ValueDetection")) or _extract_text(field.get("Value"))
                        if not value:
                            value = _extract_text(field)
                        if key in {"description", "item", "product", "name"}:
                            item["description"] = value
                        elif key in {"quantity", "qty"}:
                            item["quantity"] = _to_number(value)
                        elif key in {"unitprice", "unit_price", "price"}:
                            item["unit_price"] = _to_number(value)
                        elif key in {"amount", "total", "line_total"}:
                            item["amount"] = _to_number(value)
                        else:
                            if value and key:
                                item[key] = value
                if item:
                    items.append(item)
    return items


def extract_invoice_fields(document_bytes: bytes) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line-item fields from an invoice using Amazon Textract AnalyzeExpense.

    Requires AWS credentials configured via environment variables or IAM role.
    """
    textract = boto3.client("textract")
    response = textract.analyze_expense(Document={"Bytes": document_bytes})

    expense_docs = response.get("ExpenseDocuments", []) or []
    vendor = None
    date = None
    total = None

    if expense_docs:
        doc = expense_docs[0]
        summary_fields = doc.get("SummaryFields", []) or []
        for field in summary_fields:
            if not isinstance(field, dict):
                continue
            ftype = _safe_get(field, "Type", "Text") or _safe_get(field, "Type", "Value")
            if isinstance(ftype, dict):
                ftype = ftype.get("Text") or ftype.get("Value")
            key = str(ftype).lower() if ftype else ""
            value = _extract_text(field.get("ValueDetection")) or _extract_text(field.get("Value"))
            if key in {"vendor_name", "supplier_name", "seller_name", "vendor"} and not vendor:
                vendor = value
            elif key in {"invoice_receipt_date", "date", "document_date"} and not date:
                date = value
            elif key in {"total", "amount_due", "invoice_total", "grand_total"} and total is None:
                total = _to_number(value)

    line_items = _normalize_line_items(expense_docs)

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
        "raw": response,
    }


def extract_invoice_fields_from_file(file_path: str) -> Dict[str, Any]:
    with open(file_path, "rb") as f:
        return extract_invoice_fields(f.read())
